  .overlay button:hover { background: #f09a4d; }
  #matchend { display: none; }

  /* Screen effects */
  #vignette { position: fixed; inset: 0; pointer-events: none; background: radial-gradient(ellipse at center, transparent 52%, rgba(190,20,10,0.5) 100%); opacity: 0; transition: opacity 0.25s; z-index: 2; }
  #flash-overlay { position: fixed; inset: 0; pointer-events: none; background: #fff; opacity: 0; z-index: 2; }
